rule_config.rego:
package tracelet.policy

import rego.v1

default matched := false
default reason := ""

tool_input := ti if {
	ti := object.get(input.event, ["raw_json", "tool_input"], {})
	is_object(ti)
}

default tool_input := {}

candidate_texts contains t if {
	some k in ["content", "new_string", "new_str", "text", "code", "contents"]
	t := object.get(tool_input, k, "")
	is_string(t)
	t != ""
}

candidate_texts contains t if {
	some e in object.get(tool_input, "edits", [])
	is_object(e)
	t := object.get(e, "new_string", "")
	is_string(t)
	t != ""
}

candidate_texts contains t if {
	t := object.get(input.event, "command_text", "")
	is_string(t)
	t != ""
}

scan_text := concat("\n", [t | some t in candidate_texts])

file_path := object.get(input.event, "file_path", "")

# High-cost instance / node classes written into IaC (Terraform, CFN, CDK).
expensive_re := `(?i)(?:instance_type|InstanceType|instanceType|db_instance_class|DBInstanceClass|instance_class|node_type|NodeType|cache_node_type|CacheNodeType)\s*[=:]\s*['"]?((?:db\.|cache\.|ml\.)?(?:p[2-5]|g[3-6]|inf\d?|trn\d?|dl\d|x\d[a-z]*|u-\d+tb\d?|hpc\d[a-z]*|f1|vt1|ra3|dc2|ds2)[a-z0-9]*\.[a-z0-9]+|(?:db\.|cache\.|ml\.)?[a-z0-9-]+\.(?:metal(?:-\d+xl)?|(?:8|9|12|16|18|24|32|48|56|96|112)xlarge))`

hits contains h if {
	some m in regex.find_all_string_submatch_n(expensive_re, scan_text, -1)
	h := m[1]
}

matched if {
	scan_text != ""
	count(hits) > 0
}

reason := sprintf("High-cost instance class %v written to %s — confirm the sizing is intentional and that the plan's cost impact has been reviewed before apply", [sort(hits), display_path]) if {
	matched
}

display_path := file_path if { file_path != "" }
display_path := "the command" if { file_path == "" }
